mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.CODE_VALUE,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.NAME_KO,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.CODE_SET_ID = #{codeSetId}
AND T1.CODE_VALUE = #{codeValue}
AND T1.ACTIVE_YN = #{activeYn}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.CODE_SET_ID AS CODE_SET_ID, S.CODE_SET_NAME AS CODE_SET_NAME, T1.CODE_VALUE AS CODE_VALUE,
           T1.NAME_KO AS NAME_KO, T1.SORT_ORDER AS SORT_ORDER, T1.ACTIVE_YN AS ACTIVE_YN, T1.REMARK AS REMARK,
           T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM, T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_CODE_VALUE_PILOT T1
      LEFT JOIN TB_IF_CODE_SET_PILOT S ON S.CODE_SET_ID = T1.CODE_SET_ID

     ORDER BY T1.CODE_SET_ID ASC, T1.SORT_ORDER ASC, T1.CODE_VALUE ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.update:
UPDATE TB_IF_CODE_VALUE_PILOT SET NAME_KO=#{nameKo}, SORT_ORDER=#{sortOrder}, ACTIVE_YN=#{activeYn},
  REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE CODE_SET_ID=#{codeSetId} AND CODE_VALUE=#{codeValue}
